import os
import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json"})

token = os.getenv("API_TOKEN")
if token:
    session.headers.update({"Authorization": f"Bearer {token}"})


def get_json(path):
    response = session.get(f"{BASE_URL}{path}")
    response.raise_for_status()
    return response.json()


top_categories = get_json("/product-categories/top")
inventory = get_json("/inventory-levels")
retailers = get_json("/retailers")

category_names = {
    item.get("category")
    for item in top_categories
    if isinstance(item, dict) and item.get("category")
}

retailer_products = {}
for retailer in retailers:
    retailer_id = retailer.get("retailer_id")
    if not retailer_id:
        continue
    response = session.get(
        f"{BASE_URL}/retailers/{retailer_id}/products"
    )
    response.raise_for_status()
    retailer_products[retailer_id] = response.json()

retailers_by_category = {category: [] for category in category_names}
for retailer in retailers:
    retailer_id = retailer.get("retailer_id")
    for product in retailer_products.get(retailer_id, []):
        category = product.get("category")
        if category in retailers_by_category:
            retailers_by_category[category].append(
                {
                    "retailer_id": retailer_id,
                    "name": retailer.get("name"),
                    "locations": retailer.get("locations", []),
                    "product": product,
                }
            )

inventory_by_product = {}
for item in inventory:
    inventory_by_product.setdefault(item.get("product_id"), []).append(item)

analysis = []
gaps = []

for category in top_categories:
    category_name = category.get("category")
    matching_products = []
    for retailer_id, products in retailer_products.items():
        for product in products:
            if product.get("category") == category_name:
                matching_products.append(
                    {
                        "retailer_id": retailer_id,
                        "product": product,
                        "inventory": inventory_by_product.get(
                            product.get("product_id"), []
                        ),
                    }
                )

    if not matching_products:
        gaps.append(
            {
                "category": category_name,
                "issue": "No retailer products found for this in-demand category.",
            }
        )

    for entry in matching_products:
        if not entry["inventory"]:
            gaps.append(
                {
                    "category": category_name,
                    "product_id": entry["product"].get("product_id"),
                    "issue": "No inventory records found across store locations.",
                }
            )
        elif all(item.get("stock_level", 0) <= 0 for item in entry["inventory"]):
            gaps.append(
                {
                    "category": category_name,
                    "product_id": entry["product"].get("product_id"),
                    "issue": "Product has no positive stock at any listed location.",
                }
            )

    analysis.append(
        {
            "category": category_name,
            "demandScore": category.get("demandScore"),
            "products": matching_products,
            "retailers": retailers_by_category.get(category_name, []),
        }
    )

feedback = {
    "subject": "Product availability and category representation analysis",
    "gaps_or_discrepancies": gaps,
    "summary": {
        "top_categories": top_categories,
        "available_retailers": retailers,
        "category_analysis": analysis,
    },
}

# No feedback-submission endpoint is documented; retain the feedback for review.
print(feedback)

