import requests
from datetime import datetime, timedelta, timezone

BASE_URL = "https://api.socbench.example"

sensor_id = "A1"
end_time = datetime.now(timezone.utc)
start_time = end_time - timedelta(days=7)

response = requests.get(
    f"{BASE_URL}/sensors/{sensor_id}/data",
    params={
        "from": start_time.isoformat(),
        "to": end_time.isoformat(),
    },
)
response.raise_for_status()
sensor_data = response.json()

values = [
    item["value"]
    for item in sensor_data
    if isinstance(item.get("value"), (int, float))
]

if values:
    mean_value = sum(values) / len(values)
    variance = sum((value - mean_value) ** 2 for value in values) / len(values)
    std_dev = variance ** 0.5
    anomalies = [
        item
        for item in sensor_data
        if isinstance(item.get("value"), (int, float))
        and std_dev > 0
        and abs(item["value"] - mean_value) > 2 * std_dev
    ]

    analysis_data = [
        {
            "componentId": sensor_id,
            "metricType": "sensor_reading",
            "values": values,
        }
    ]

    prediction_response = requests.post(
        f"{BASE_URL}/predictive-analysis",
        json={"data": analysis_data},
    )
    prediction_response.raise_for_status()

    result = {
        "trend": {
            "first_value": values[0],
            "last_value": values[-1],
            "change": values[-1] - values[0],
            "mean": mean_value,
        },
        "anomalies": anomalies,
        "predictions": prediction_response.json(),
    }
else:
    result = {
        "trend": None,
        "anomalies": [],
        "predictions": None,
        "message": "No numeric sensor readings were returned for the past week.",
    }

print(result)
